var e={id:`newzealand`,flag:`🇳🇿`,names:{en:`New Zealand`,zh:`新西兰`,de:`Neuseeland`,fr:`Nouvelle-Zélande`,es:`Nueva Zelanda`,tr:`Yeni Zelanda`},region:`oceania`,langCode:`en-NZ`,greetings:[{native:`Kia ora`,meaning:{en:`Hello (Maori)`,zh:`你好（毛利语）`}},{native:`Hello`,meaning:{en:`Hello`,zh:`你好`}}],commonPhrases:[{native:`Kia ora`,meaning:{en:`Hello / Thank you (Maori)`,zh:`你好 / 谢谢 (毛利语)`}},{native:`How are you?`,meaning:{en:`How are you?`,zh:`你好吗？`}},{native:`Good thanks`,meaning:{en:`Good, thanks`,zh:`很好，谢谢`}},{native:`Cheers`,meaning:{en:`Thanks / Goodbye`,zh:`谢谢 / 再见`}},{native:`Please`,meaning:{en:`Please`,zh:`请`}},{native:`Sweet as`,meaning:{en:`No problem / That is cool (NZ idiom)`,zh:`没问题 / 太酷了 (新西兰用语)`}}],food:[{name:{en:`Hangi`,zh:`杭伊地下窑烤`},desc:{en:`Maori underground oven cooking using heated stones`,de:`Maori-Erdofen-Kochen mit erhitzten Steinen`,zh:`使用加热石头的毛利地下窑烤烹饪`},emoji:`🍖`,img:``},{name:{en:`Pavlova`,zh:`帕夫洛娃蛋糕`},desc:{en:`Meringue dessert topped with fruit and cream`,de:`Baiser-Dessert mit Obst und Sahne`,zh:`配水果和奶油的蛋白甜饼甜点`},emoji:`🍰`,img:`https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Pavlova.jpg/320px-Pavlova.jpg`},{name:{en:`Meat Pie`,zh:`肉派`},desc:{en:`Popular savory pastry snack`,de:`Beliebter herzhafter Geback-Snack`,zh:`受欢迎的咸味酥皮馅饼小吃`},emoji:`🥧`,img:``}],festivals:[{name:{en:`Waitangi Day`,zh:`怀唐伊日`},desc:{en:`February 6th commemorating the Treaty of Waitangi signing in 1840`,de:`6. Februar, Gedenken an die Unterzeichnung des Vertrags von Waitangi 1840`,zh:`二月六日纪念1840年怀唐伊条约签署`},emoji:`🇳🇿`,img:``},{name:{en:`Matariki`,zh:`毛利新年`},desc:{en:`Maori New Year based on the Pleiades star cluster rising`,de:`Maori-Neujahr basierend auf dem Aufgang des Plejaden-Sternhaufens`,zh:`基于昂宿星团升起的毛利新年`},emoji:`✨`,img:``}],landmarks:[{name:{en:`Hobbiton`,zh:`霍比特人村`},img:`https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Hobbiton.jpg/320px-Hobbiton.jpg`},{name:{en:`Milford Sound`,zh:`米尔福德峡湾`},img:`https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Milford_Sound.jpg/320px-Milford_Sound.jpg`},{name:{en:`Tongariro National Park`,zh:`汤加里罗国家公园`},img:``}],etiquette:[{emoji:`🌿`,tip:{en:`Respect Maori culture and customs, including the hongi greeting`,zh:`尊重毛利文化和习俗，包括碰鼻礼`}},{emoji:`👟`,tip:{en:`Remove shoes when entering a Maori meeting house (marae)`,zh:`进入毛利会堂时要脱鞋`}}],funFacts:[{en:`New Zealand has about 30 million sheep vs 5 million people`,de:`Neuseeland hat etwa 30 Millionen Schafe gegenuber 5 Millionen Menschen`,zh:`新西兰约有3,000万只羊 vs 500万人`},{en:`New Zealand was the first country to give women the right to vote in 1893`,de:`Neuseeland war 1893 das erste Land, das Frauen das Wahlrecht gab`,zh:`新西兰是第一个在1893年给女性投票权的国家`},{en:`New Zealand was the last large landmass settled by humans (c. 1300 AD)`,de:`Neuseeland war die letzte grosse Landmasse, die von Menschen besiedelt wurde`,zh:`新西兰是最后一个有人类定居的大型陆地（约公元1300年）`}],biases:[{type:`myth`,statement:{en:`All New Zealanders are Hobbits`,de:`Alle Neuseelander sind Hobbits`,zh:`所有新西兰人都是霍比特人`},explanation:{en:`This is a Lord of the Rings movie reference, not reality`,de:`Dies ist ein Filmverweis auf Der Herr der Ringe, nicht die Realitat`,zh:`这是《指环王》电影引用，不是现实`}},{type:`fact`,statement:{en:`New Zealand has more sheep than people`,zh:`新西兰的羊比人多`},explanation:{en:`About 30 million sheep compared to 5 million people`,de:`Etwa 30 Millionen Schafe im Vergleich zu 5 Millionen Menschen`,zh:`约3,000万只羊对比500万人`}},{type:`myth`,statement:{en:`All New Zealanders speak Maori`,de:`Alle Neuseelander sprechen Maori`,zh:`所有新西兰人都讲毛利语`},explanation:{en:`Only about 4% speak Maori as their first language, though it is an official language`,de:`Nur etwa 4% sprechen Maori als Muttersprache, obwohl es eine Amtssprache ist`,zh:`只有约4%的人以毛利语为第一语言，不过它是官方语言之一`}},{type:`fact`,statement:{en:`New Zealand was the first country to give women the vote`,zh:`新西兰是第一个给女性投票权的国家`},explanation:{en:`Women won the right to vote in national elections in 1893`,de:`Frauen erhielten 1893 das Wahlrecht bei nationalen Wahlen`,zh:`女性于1893年获得全国选举投票权`}},{type:`myth`,statement:{en:`New Zealand is just like Australia`,de:`Neuseeland ist genau wie Australien`,zh:`新西兰和澳大利亚一样`},explanation:{en:`NZ has distinct Maori culture, different accent, and a separate national identity`,de:`Neuseeland hat eine ausgepragte Maori-Kultur, einen anderen Akzent und eine eigene nationale Identitat`,zh:`新西兰有独特的毛利文化、不同的口音和独立的国家认同`}}],quickStats:[{label:{en:`Population`,zh:`人口`},value:`~5.1 million`,emoji:`👥`},{label:{en:`Area`,zh:`面积`},value:`268,021 km²`,emoji:`🗺️`},{label:{en:`Capital`,zh:`首都`},value:`Wellington`,emoji:`🏛️`}],musicOrArt:[{name:{en:`Maori Haka`,zh:`毛利战舞`},desc:{en:`Traditional Maori war dance made famous by the All Blacks rugby team`,de:`Traditioneller Maori-Kriegstanz, beruhmt durch die All Blacks Rugby-Mannschaft`,zh:`由全黑橄榄球队推广的传统毛利战舞`},emoji:`💪`},{name:{en:`Maori Carving`,zh:`毛利木雕`},desc:{en:`Intricate wood carving tradition telling ancestral stories`,de:`Aufwandige Holzschnitzereitradition, die Vorfahrengeschichten erzahlt`,zh:`讲述祖先故事的精细木雕传统`},emoji:`🪵`}]};export{e as newzealand};